// CPU-only independent checking/capture ABI: no GPU body or scientific force driver.
#include "study_observer.h"
#include "study_input.h"
#include <filesystem>
#include <memory>
#include <limits>
#include <algorithm>
#include <map>
#include <sstream>
#include <iomanip>
#include <cmath>
#include <cstdio>
#include <cstring>
#include <chrono>
#include <unistd.h>
#include <openssl/sha.h>
#include <zlib.h>
static std::vector<std::unique_ptr<SnapInput>>cfg;static std::vector<std::vector<double>>oracles,hin;static std::filesystem::path root,casdir;static std::string model,nonce;static int trial_;static std::ofstream guards_,ledger_;static std::vector<double>prefix_,out_;static double error_,normalized_,sse_[3];static int outputs_[3];static const int orders[]={14,4,2},steps_[]={100,3,3};
static void need(bool b,const char*s){if(!b)throw std::runtime_error(s);}
static std::string hash(const void*p,size_t n){unsigned char b[32];SHA256((const unsigned char*)p,n,b);std::ostringstream s;for(auto c:b)s<<std::hex<<std::setw(2)<<std::setfill('0')<<unsigned(c);return s.str();}
static std::string keep(const unsigned char*p,size_t n){auto h=hash(p,n);auto dest=casdir/(h+".bin.gz");if(!std::filesystem::exists(dest)){auto temp=dest.string()+".tmp"+std::to_string(getpid());gzFile f=gzopen(temp.c_str(),"wb1");need(f,"CAS create");size_t at=0;while(at<n){int k=std::min<size_t>(1<<20,n-at);need(gzwrite(f,p+at,k)==k,"CAS write");at+=k;}need(gzclose(f)==Z_OK,"CAS close");std::filesystem::rename(temp,dest);}return h;}
template<class F>static void safe(F f){try{f();}catch(const std::exception&e){fprintf(stderr,"SNAP_OBSERVER %s\n",e.what());fflush(stderr);std::abort();}}
extern "C" void snap_start(const char*m,const char*source,const char*captures){safe([&](){model=m;root=std::filesystem::path(captures)/model;casdir=std::filesystem::path(captures)/"CAS";std::filesystem::create_directories(root);std::filesystem::create_directories(casdir);nonce=std::to_string(std::chrono::system_clock::now().time_since_epoch().count())+"_"+std::to_string(getpid());for(int j:orders){auto stem=std::string("J")+std::to_string(j);cfg.emplace_back(std::make_unique<SnapInput>((std::filesystem::path(source)/"data"/(stem+"_source_fixture.bin")).string()));auto&s=*cfg.back();std::ifstream f(std::filesystem::path(source)/"data"/(stem+"_independent_oracle.bin"),std::ios::binary);std::vector<double>v(3*s.na*s.nb+3*s.nt);f.read((char*)v.data(),v.size()*8);need(bool(f),"independent oracle length");char b;need(!f.read(&b,1),"oracle trailing");oracles.push_back(std::move(v));hin.emplace_back(s.inside.begin(),s.inside.end());}});}
extern "C" void snap_begin(int t){safe([&](){trial_=t;prefix_.clear();out_.clear();error_=normalized_=0;memset(outputs_,0,sizeof(outputs_));memset(sse_,0,sizeof(sse_));if(guards_.is_open())guards_.close();if(ledger_.is_open())ledger_.close();auto stem=nonce+"_trial"+std::to_string(t);guards_.open(root/(stem+".guards.bin"),std::ios::binary);ledger_.open(root/(stem+".inputs.jsonl"));need(bool(guards_)&&bool(ledger_),"capture file open");printf("SNAP_CAPTURES model=%s trial=%d guards=%s inputs=%s\n",model.c_str(),t,(root/(stem+".guards.bin")).c_str(),(root/(stem+".inputs.jsonl")).c_str());fflush(stdout);});}
extern "C" void snap_case(int ci,const uint32_t*h,const double*p,int steps){safe([&](){auto&s=*cfg.at(ci);need(steps==steps_[ci],"case repeat scope");need(memcmp(h,s.h,48)==0&&memcmp(p,s.scalars,32)==0,"actual scalar/header fixture");for(int k=0;k<12;k++)prefix_.push_back(h[k]);for(int k=0;k<4;k++)prefix_.push_back(p[k]);prefix_.push_back(steps);});}
static std::pair<const void*,size_t>expected(int ci,int id,bool&integer){auto&s=*cfg.at(ci);integer=id<5;switch(id){case 0:return{s.iu.data(),s.iu.size()*4};case 1:return{s.parity.data(),s.parity.size()*4};case 2:return{s.id.data(),s.id.size()*4};case 3:return{s.iz.data(),s.iz.size()*4};case 4:return{s.icg.data(),s.icg.size()*4};case 5:return{s.root.data(),s.root.size()*8};case 6:return{s.cg.data(),s.cg.size()*8};case 7:return{s.zbeta.data(),s.zbeta.size()*8};case 8:return{s.rij.data(),s.rij.size()*8};case 9:return{s.w.data(),s.w.size()*8};case 10:return{s.rcut.data(),s.rcut.size()*8};case 11:return{hin[ci].data(),hin[ci].size()*8};case 12:return{s.reference.data(),s.reference.size()*8};case 13:return{s.coeff.data(),s.coeff.size()*8};default:throw std::runtime_error("input ID");}}
extern "C" void snap_input(int ci,int step,int id,const unsigned char*p,size_t n){safe([&](){bool integer;auto x=expected(ci,id,integer);auto sha=keep(p,n);ledger_<<"{\"case\":"<<ci<<",\"step\":"<<step<<",\"id\":"<<id<<",\"device_input\":"<<(id<=10?"true":"false")<<",\"bytes\":"<<n<<",\"sha256\":\""<<sha<<"\"}\n";ledger_.flush();need(n==x.second&&memcmp(p,x.first,n)==0,"full actual input bit comparison");bool append=(id<8&&step==0)||(id>=8&&id<=11&&step==1)||(id>=12&&step==0);if(append){if(integer){auto a=(const int32_t*)p;for(size_t i=0;i<n/4;i++)prefix_.push_back(a[i]);}else{auto a=(const double*)p;prefix_.insert(prefix_.end(),a,a+n/8);}}});}
extern "C" void snap_guard(int ci,int step,int id,const unsigned char*p){safe([&](){int32_t h[]={ci,step,id,512};guards_.write((char*)h,16);guards_.write((const char*)p,512);need(bool(guards_),"guard write");for(int k=0;k<512;k++)need(p[k]==0xa5,"actual guard mismatch");});}
extern "C" void snap_output(int ci,int step,const double*d,const double*f){safe([&](){auto&s=*cfg.at(ci);need(step==outputs_[ci]+1,"complete step output sequence");size_t nd=3*s.na*s.nb,nf=3*s.nt;out_.push_back(ci);out_.push_back(step);out_.insert(out_.end(),d,d+nd);out_.insert(out_.end(),f,f+nf);auto check=[&](double a,double b){need(std::isfinite(a)&&std::isfinite(b),"nonfinite output/oracle");double e=std::abs(a-b);error_=std::max(error_,e);double ratio=e/(1e-7+1e-9*std::abs(b));normalized_=std::max(normalized_,ratio);need(ratio<=1,"independent full force/gradient budget");};for(size_t i=0;i<nd;i++)check(d[i],oracles[ci][i]);for(size_t i=0;i<nf;i++)check(f[i],oracles[ci][nd+i]);if(s.J!=4)for(size_t i=0;i<nf;i++)check(f[i],s.reference[i]);
for(int atom=0;atom<s.nt;atom++){double x=f[atom]-s.reference[atom],y=f[atom+s.nt]-s.reference[atom+s.nt],z=f[atom+2*s.nt]-s.reference[atom+2*s.nt];sse_[ci]+=x*x+y*y+z*z;}
for(int k=0;k<3;k++){long double sum=0,total=0;for(int atom=0;atom<s.nt;atom++)sum+=f[atom+s.nt*k];for(int pair=0;pair<s.na*s.nb;pair++)total+=std::abs(d[pair+s.na*s.nb*k]);long double bound=1e-12L+8*std::numeric_limits<double>::epsilon()*s.na*s.nb*total;need(fabsl(sum)<=bound,"action reaction net force budget");}outputs_[ci]++;});}
extern "C" void snap_case_end(int ci,double actual_sse){safe([&](){auto&s=*cfg.at(ci);need(outputs_[ci]==steps_[ci],"all source steps retained");need(std::isfinite(actual_sse)&&std::abs(actual_sse-sse_[ci])<=1e-18+1e-12*std::abs(sse_[ci]),"own source SSE accumulation");out_.push_back(actual_sse);out_.push_back(sqrt(actual_sse/(s.nt*steps_[ci])));printf("SNAP_CASE trial=%d J=%d steps=%d author_RMS=%.17g author_reference_used=%s\n",trial_,s.J,steps_[ci],sqrt(actual_sse/(s.nt*steps_[ci])),s.J==4?"false_unvalidated_allzero":"true");});}
extern "C" void snap_write(int trial,double seconds){safe([&](){need(trial==trial_,"trial identity");for(int i=0;i<3;i++)need(outputs_[i]==steps_[i],"case coverage");guards_.flush();ledger_.flush();prefix_.insert(prefix_.end(),out_.begin(),out_.end());std::string file="trial"+std::to_string(trial)+".bin";std::ofstream f(file,std::ios::binary);f.write((char*)prefix_.data(),prefix_.size()*8);f.close();need(bool(f),"primary output write");printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":true,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"max_normalized_independent_budget\":%.17g,\"jit_excluded\":true,\"timing_region\":\"sum3case_full_source_step_pipelines_100plus3plus3_observer_paused\",\"internal_repeats\":1,\"case_internal_steps\":[100,3,3],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,prefix_.size(),error_,normalized_,file.c_str(),prefix_.size());fflush(stdout);});}
extern "C" void snap_finish(){safe([](){if(guards_.is_open())guards_.close();if(ledger_.is_open())ledger_.close();});}
